const notionItems = $('Get Notion Pages').all().map(i => i.json);
const googleItems = $('Get Google Tasks').all().map(i => i.json);

const NOW = Date.now();
const DAYS_14_MS = 14 * 24 * 60 * 60 * 1000;
const TASKLIST_ID = 'MDk4NTUxODgzNzA1NDM2OTIxNjg6MDow';

function safeText(v) { return (v == null ? '' : String(v)).trim(); }
function normDate(d) { return d ? String(d).slice(0, 10) : null; }
function statusToGoogle(s) { return s === 'Done' ? 'completed' : 'needsAction'; }

function inScopeGoogleTask(g) {
  if (g.status !== 'completed') return true;
  const updated = g.updated ? new Date(g.updated).getTime() : 0;
  return updated && (NOW - updated <= DAYS_14_MS);
}

const googleById = new Map();
for (const g of googleItems) {
  if (!inScopeGoogleTask(g)) continue;
  googleById.set(String(g.id), g);
}

const out = [];

for (const raw of notionItems) {
  const gid = safeText(raw.property_google_task_id || '');
  const title = safeText(raw.property_task_name || raw.name || '') || '(Untitled)';
  const nStatus = safeText(raw.property_status || 'Not started');
  const nDue = (() => {
    const d = raw.property_due_date;
    if (d && d.start) return normDate(d.start);
    if (typeof d === 'string' && d) return normDate(d);
    return null;
  })();
  const nNotes = String(raw.property_notes || '').slice(0, 8192);
  const nTasklistId = safeText(raw.property_google_tasklist_id || '') || TASKLIST_ID;

  if (!gid) {
    out.push({ json: {
      action: 'create_google',
      notionPageId: raw.id, title,
      notionStatus: nStatus,
      googleStatus: statusToGoogle(nStatus),
      dueDate: nDue, notes: nNotes,
      googleTaskId: '', googleTasklistId: TASKLIST_ID,
    }});
    continue;
  }

  const g = googleById.get(gid);
  if (!g) {
    out.push({ json: {
      action: 'skip_missing_linked',
      notionPageId: raw.id, title,
      googleTaskId: gid, googleTasklistId: nTasklistId,
    }});
    continue;
  }

  const gTitle = safeText(g.title) || '(Untitled)';
  const gStatus = g.status || 'needsAction';
  const gDue = normDate(g.due);
  const gNotes = safeText(g.notes);
  const targetGoogleStatus = statusToGoogle(nStatus);

  const titleChanged = title !== gTitle;
  const statusChanged = targetGoogleStatus !== gStatus;
  const dueChanged = nDue !== gDue;
  const notesChanged = nNotes !== gNotes;

  if (titleChanged || statusChanged || dueChanged || notesChanged) {
    out.push({ json: {
      action: 'update_google',
      notionPageId: raw.id, title,
      notionStatus: nStatus,
      googleStatus: targetGoogleStatus,
      dueDate: nDue, notes: nNotes,
      googleTaskId: gid, googleTasklistId: nTasklistId,
      changes: { title: titleChanged, status: statusChanged, due: dueChanged, notes: notesChanged },
    }});
  } else {
    out.push({ json: {
      action: 'skip_no_change',
      notionPageId: raw.id, title,
      googleTaskId: gid, googleTasklistId: nTasklistId,
    }});
  }
}

return out;

const allItems = $('Plan Notion->Google Actions').all();
let created = 0, updated = 0, skipped = 0, missingLinked = 0;
const missingLinkedIds = [];

for (const item of allItems) {
  const a = item.json.action;
  if (a === 'create_google') created++;
  else if (a === 'update_google') updated++;
  else if (a === 'skip_missing_linked') {
    missingLinked++;
    if (item.json.googleTaskId && missingLinkedIds.length < 20) {
      missingLinkedIds.push(item.json.googleTaskId);
    }
  } else skipped++;
}

return [{ json: {
  branch: 'notion_to_google',
  scanned: allItems.length,
  created, updated, skipped,
  missing_linked: missingLinked,
  missing_linked_ids: missingLinkedIds,
  timestamp: new Date().toISOString(),
}}];

